import numpy as np, math
from collections import Counter
atoms=[]
def add(el,p):
    atoms.append((el,np.array(p,dtype=float)))
    return len(atoms)-1
def unit(v):
    v=np.array(v,dtype=float); n=np.linalg.norm(v)
    if n<1e-9: raise ValueError('zero')
    return v/n
def add_methyl(ring_c, outward):
    u=unit(outward); mc=ring_c+1.50*u; add('C',mc)
    ref=np.array([0.,0.,1.])
    if abs(np.dot(ref,u))>0.88: ref=np.array([0.,1.,0.])
    a=unit(ref-np.dot(ref,u)*u); b=unit(np.cross(u,a))
    for k in range(3):
        phi=2*math.pi*k/3
        hdir=(1/3)*u+math.sqrt(8/9)*(math.cos(phi)*a+math.sin(phi)*b)
        add('H',mc+1.09*hdir)
def add_cpstar_eta(ga,axis,phase=0.0):
    n=unit(axis); ref=np.array([0.,0.,1.])
    if abs(np.dot(ref,n))>0.85: ref=np.array([0.,1.,0.])
    a=unit(ref-np.dot(ref,n)*n); b=unit(np.cross(n,a)); cent=ga+1.90*n
    ring=[]
    for j in range(5):
        t=phase+2*math.pi*j/5; radial=math.cos(t)*a+math.sin(t)*b
        c=cent+1.22*radial; add('C',c); ring.append((c,radial))
    for c,radial in ring: add_methyl(c,radial)
add('Ni',[0,0,0])
tetra={'UL':np.array([-1.,1.,1.]),'UR':np.array([1.,1.,-1.]),'LL':np.array([-1.,-1.,-1.]),'LR':np.array([1.,-1.,1.])}
G={}
for name,v in tetra.items():
    v=unit(v); G[name]=2.35*v; add('Ga',G[name])
for i,name in enumerate(('UL','UR','LL')): add_cpstar_eta(G[name],tetra[name],phase=0.15+0.41*i)
v=unit(tetra['LR']); ref=np.array([1.,0.,0.]); w=unit(ref-np.dot(ref,v)*v); e=unit(np.cross(v,w)); ga=G['LR']
loc={'Ga':(0.,0.),'N1':(1.55,1.10),'C1':(2.85,0.60),'C2':(2.70,-0.80),'N2':(1.35,-1.30)}
def tr(pt): return ga+pt[0]*w+pt[1]*e
p={k:tr(xy) for k,xy in loc.items()}
add('N',p['N1']); add('C',p['C1']); add('C',p['C2']); add('N',p['N2'])
for nk,o1,o2 in [('N1','Ga','C1'),('N2','C2','Ga')]:
    n=p[nk]; hd=unit(-(unit(p[o1]-n)+unit(p[o2]-n))); add('H',n+1.01*hd)
def external_direction(center,nbr1,nbr2): return unit(-(unit(nbr1-center)+unit(nbr2-center)))
add_methyl(p['C1'],external_direction(p['C1'],p['N1'],p['C2']))
u2=external_direction(p['C2'],p['C1'],p['N2']); rad=1.22; cent=p['C2']+2.72*u2
ring=[]
for j in range(5):
    theta=2*math.pi*j/5; radial=math.cos(theta)*(-u2)+math.sin(theta)*e
    c=cent+rad*radial; add('C',c); ring.append((c,radial))
for c,radial in ring: add_methyl(c,radial)
with open('answer.xyz','w') as f:
    f.write(f'{len(atoms)}\nApproximate 3D structure of the depicted Ni/Ga Cp* complex\n')
    for el,p0 in atoms: f.write(f'{el:2s} {p0[0]: .6f} {p0[1]: .6f} {p0[2]: .6f}\n')
print('atoms',len(atoms),Counter(e for e,p0 in atoms))
D=[]
for i in range(len(atoms)):
 for j in range(i):
  d=np.linalg.norm(atoms[i][1]-atoms[j][1])
  if d<0.75: D.append((d,i,j,atoms[i][0],atoms[j][0]))
print('pairs <0.75',D[:20])
print('min',min(np.linalg.norm(atoms[i][1]-atoms[j][1]) for i in range(len(atoms)) for j in range(i)))
